API Gateway Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway_container, "API Gateway Container") {
    Component(Ingress_Proxy_Routing_Component, "Ingress Proxy & Routing Component", "Kubernetes Ingress / Custom Proxy", "Handles secure user access, HTTPS/MFS enforcement, and internal microservice routing via gRPC/REST.")
    Component(Authentication_Token_Validation_Component, "Authentication & Token Validation Component", "OAuth2 / JWT & W3C Trace Context", "Performs token introspection and JWT validation via HTTPS with External Identity Providers (IdPs).")
    Component(Rate_Limiting_Session_Management_Component, "Rate Limiting & Session Management Component", "Redis Enterprise", "Manages session persistence, distributed rate limiting, and idempotency tracking via TCP.")
}

Rel(Ingress_Proxy_Routing_Component, Authentication_Token_Validation_Component, "Validates incoming tokens and enforces security")
Rel(Ingress_Proxy_Routing_Component, Rate_Limiting_Session_Management_Component, "Tracks session persistence and distributed rate limiting via TCP")

@enduml

Domain Containers.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(domain_containers, "Domain Containers") {
    Component(EMR_Service, "EMR Service", "Microservice / gRPC / REST", "Manages electronic medical records, patient admissions, and clinical data.")
    Component(Scheduling_Service, "Scheduling Service", "Microservice / gRPC / REST", "Handles appointments, practitioner schedules, and resource allocation.")
    Component(Billing_Service, "Billing Service", "Microservice / gRPC / REST", "Processes financial operations, invoices, and third-party billing integrations.")
}

Rel(EMR_Service, Scheduling_Service, "Coordinates patient appointments and medical history access", "gRPC/REST")
Rel(Scheduling_Service, Billing_Service, "Triggers billing workflows upon appointment completion", "gRPC/REST")

@enduml

Integration Service Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(IntegrationServiceContainer, "Integration Service Container") {
    Component(HL7FHIRWorker, "HL7 FHIR Worker", "Asynchronous Worker / Streaming JSON Parsers", "Processes HL7 FHIR traffic and external system interactions with memory-efficient payload parsing.")
    Component(CircuitBreakerDLQHandler, "Circuit Breaker & DLQ Handler", "Circuit Breaker & Dead-Letter Queue (DLQ)", "Handles errors and external communication failures with PII/PHI sanitization.")
    Component(TransactionalOutboxDispatcher, "Transactional Outbox Dispatcher", "Transactional Outbox Pattern", "Ensures atomic state changes and message dispatches to prevent split-brain issues.")
}

Rel(HL7FHIRWorker, CircuitBreakerDLQHandler, "Routes failed external calls and sanitizes errors via [Circuit Breaker/DLQ]")
Rel(TransactionalOutboxDispatcher, HL7FHIRWorker, "Dispatches atomic state changes and messages via [AMQP/TCP or Kafka Protocol]")

@enduml

Event Bus / Message Broker Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Event Bus / Message Broker Container container

Container_Boundary(event_bus_container, "Event Bus / Message Broker Container") {
    Component(Event_Broker_Cluster, "Event Broker Cluster", "Apache Kafka", "Append-only commit log supporting 10-year auditability, event sourcing, and pub/sub message distribution.")
    Component(Schema_Registry, "Schema Registry", "Confluent Schema Registry", "Enforces backward and forward compatibility and validates payload schemas for all domain events.")
}

Rel(Event_Broker_Cluster, Schema_Registry, "Validates event schemas", "REST")

@enduml

Caching Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
