File/Document Storage Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the File/Document Storage Container container

Container_Boundary(file_document_storage_container, "File/Document Storage Container") {
